	if loop.IsEmpty() {
		return &LaxLoop{}
	}

	l := &LaxLoop{
		numVertices: len(loop.vertices),
		vertices:    make([]Point, len(loop.vertices)),
	}
	copy(l.vertices, loop.vertices)
	return l
}

