		shapes:          make(map[int32]Shape, min(numShapes, decodeAllocChunk)),
		maxEdgesPerCell: maxEdges,
		nextID:          int32(nextID),
		cellMap:         make(map[CellID]*ShapeIndexCell),
	}

	prevID := -1
	for range numShapes {
		id := readCount(d, uint64(nextID-1), "shape ID")
		if d.err != nil {
			return nil
		}
		if id <= prevID {
			setDecodeErr(d, "shape IDs out of order: %d after %d", id, prevID)
			return nil
