package s2

import (
	"bytes"
	"encoding/binary"
	"fmt"
	"math/rand"
	"reflect"
	"testing"
)

func encodeShapeIndexOrDie(t *testing.T, index *ShapeIndex) []byte {
	t.Helper()
	var buf bytes.Buffer
	if err := index.Encode(&buf); err != nil {
		t.Fatalf("Encode() failed: %v", err)
	}
	return buf.Bytes()
}

func roundTripShapeIndex(t *testing.T, index *ShapeIndex) *ShapeIndex {
	t.Helper()
	data := encodeShapeIndexOrDie(t, index)
	got := &ShapeIndex{}
	if err := got.Decode(bytes.NewReader(data)); err != nil {
		t.Fatalf("Decode() failed: %v", err)
	}
	return got
}

// shapeIndexCellsString returns a description of the cell structure of the
// index, obtained through the public iterator.
func shapeIndexCellsString(index *ShapeIndex) string {
	var buf bytes.Buffer
	for it := index.Iterator(); !it.Done(); it.Next() {
		fmt.Fprintf(&buf, "%v:", it.CellID())
		for _, c := range it.IndexCell().shapes {
			fmt.Fprintf(&buf, " {%d %v %v}", c.shapeID, c.containsCenter, c.edges)
		}
		buf.WriteString("\n")
	}
	return buf.String()
}

func checkShapeIndexEqual(t *testing.T, want, got *ShapeIndex) {
	t.Helper()
	if got.Len() != want.Len() {
		t.Fatalf("Len() = %d, want %d", got.Len(), want.Len())
	}
	if got.nextID != want.nextID {
		t.Errorf("nextID = %d, want %d", got.nextID, want.nextID)
	}
	if got.maxEdgesPerCell != want.maxEdgesPerCell {
		t.Errorf("maxEdgesPerCell = %d, want %d", got.maxEdgesPerCell, want.maxEdgesPerCell)
	}
	if !got.IsFresh() {
		t.Errorf("decoded index is not fresh")
	}
	for id, ws := range want.shapes {
		gs := got.Shape(id)
		if gs == nil {
			t.Errorf("shape %d missing after decode", id)
			continue
		}
		if reflect.TypeOf(gs) != reflect.TypeOf(ws) {
			t.Errorf("shape %d type = %T, want %T", id, gs, ws)
		}
		if gs.Dimension() != ws.Dimension() || gs.NumEdges() != ws.NumEdges() ||
			gs.NumChains() != ws.NumChains() || gs.IsEmpty() != ws.IsEmpty() ||
			gs.IsFull() != ws.IsFull() || gs.ReferencePoint() != ws.ReferencePoint() {
			t.Errorf("shape %d properties differ after decode", id)
		}
		for e := 0; e < ws.NumEdges(); e++ {
			if gs.Edge(e) != ws.Edge(e) {
				t.Errorf("shape %d edge %d = %v, want %v", id, e, gs.Edge(e), ws.Edge(e))
			}
		}
		for c := 0; c < ws.NumChains(); c++ {
			if gs.Chain(c) != ws.Chain(c) {
				t.Errorf("shape %d chain %d = %v, want %v", id, c, gs.Chain(c), ws.Chain(c))
			}
		}
	}
	if w, g := shapeIndexCellsString(want), shapeIndexCellsString(got); w != g {
		t.Errorf("cell structure differs:\ngot:\n%s\nwant:\n%s", g, w)
	}
	if !got.IsFresh() {
		t.Errorf("iterating decoded index triggered a rebuild")
	}
}

func allShapeTypesIndex() *ShapeIndex {
	index := NewShapeIndex()
	pv := PointVector(parsePoints("0:0 | 1:1 | 2:2"))
	index.Add(&pv)
	index.Add(makePolyline("0:0, 2:1, 5:5"))
	index.Add(makeLoop("0:0, 0:5, 5:5, 5:0"))
	index.Add(makePolygon("10:10, 10:20, 20:20, 20:10; 12:12, 18:12, 18:18, 12:18", true))
	index.Add(makeLaxPolyline("-5:-5, -6:-7, -8:-9"))
	index.Add(LaxLoopFromPoints(parsePoints("30:30, 30:35, 35:35")))
	index.Add(makeLaxPolygon("40:40, 40:45, 45:45; 41:41, 42:41, 42:42"))
	index.Add(FullLoop())
	index.Add(PolygonFromLoops([]*Loop{FullLoop()}))
	return index
}

func TestShapeIndexEncodeDecodeAllShapeTypes(t *testing.T) {
	index := allShapeTypesIndex()
	index.Build()
	got := roundTripShapeIndex(t, index)
	checkShapeIndexEqual(t, index, got)

	// Queries must agree.
	wantQ := NewContainsPointQuery(index, VertexModelSemiOpen)
	gotQ := NewContainsPointQuery(got, VertexModelSemiOpen)
	for i := 0; i < 1000; i++ {
		p := randomPoint()
		if i < 4 {
			p = parsePoint([]string{"2:2", "15:15", "13:13", "31:32"}[i])
		}
		w, g := wantQ.ContainingShapes(p), gotQ.ContainingShapes(p)
		if len(w) != len(g) {
			t.Fatalf("ContainingShapes(%v) = %d shapes, want %d", p, len(g), len(w))
		}
		for j := range w {
			if got.idForShape(g[j]) != index.idForShape(w[j]) {
				t.Errorf("ContainingShapes(%v) mismatch", p)
			}
		}
	}
	if !got.IsFresh() {
		t.Errorf("querying decoded index triggered a rebuild")
	}
}

func TestShapeIndexEncodeDecodeEmpty(t *testing.T) {
	index := NewShapeIndex()
	data := encodeShapeIndexOrDie(t, index)
	if len(data) == 0 {
		t.Fatalf("empty index encoded to zero bytes")
	}
	got := &ShapeIndex{}
	if err := got.Decode(bytes.NewReader(data)); err != nil {
		t.Fatalf("Decode() failed: %v", err)
	}
	checkShapeIndexEqual(t, index, got)
	if !got.Iterator().Done() {
		t.Errorf("decoded empty index has cells")
	}

	// A decoded empty index can still be used incrementally.
	got.Add(makePolyline("0:0, 1:1"))
	if got.Iterator().Done() {
		t.Errorf("adding to decoded empty index produced no cells")
	}
}

func TestShapeIndexEncodeDecodeZeroEdgeAndMixedChains(t *testing.T) {
	index := NewShapeIndex()
	empty := PointVector{}
	index.Add(&empty)
	index.Add(&Polyline{})
	index.Add(LaxPolylineFromPoints(nil))
	index.Add(LaxPolylineFromPoints(parsePoints("1:1")))
	index.Add(&LaxLoop{})
	index.Add(EmptyLoop())
	index.Add(&Polygon{})
	index.Add(LaxPolygonFromPoints(nil))
	index.Add(LaxPolygonFromPoints([][]Point{{}}))
	index.Add(LaxPolygonFromPoints([][]Point{{}, parsePoints("0:0, 0:3, 3:3"), {}, parsePoints("1:1"), parsePoints("5:5, 5:6")}))
	index.Add(makeLaxPolygon("0:0, 0:3, 3:3"))
	index.Build()

	got := roundTripShapeIndex(t, index)
	checkShapeIndexEqual(t, index, got)
}

func TestShapeIndexEncodeWithoutBuild(t *testing.T) {
	index := allShapeTypesIndex()
	if index.IsFresh() {
		t.Fatalf("index unexpectedly fresh before Build")
	}
	got := roundTripShapeIndex(t, index)

	want := allShapeTypesIndex()
	want.Build()
	checkShapeIndexEqual(t, want, got)
}

func TestShapeIndexEncodeDecodePreservesShapeIDs(t *testing.T) {
	index := NewShapeIndex()
	var shapes []Shape
	for i := 0; i < 6; i++ {
		shapes = append(shapes, makeLoop(fmt.Sprintf("%d:0, %d:1, %d:1", i*3, i*3, i*3+1)))
		index.Add(shapes[i])
	}
	index.Remove(shapes[0])
	index.Remove(shapes[3])
	got := roundTripShapeIndex(t, index)
	checkShapeIndexEqual(t, index, got)
	if got.Shape(0) != nil || got.Shape(3) != nil {
		t.Errorf("removed shapes reappeared after decode")
	}
	for _, id := range []int32{1, 2, 4, 5} {
		if got.Shape(id) == nil {
			t.Errorf("shape %d missing after decode", id)
		}
	}
	if id := got.Add(makePolyline("0:0, 1:1")); id != 6 {
		t.Errorf("Add after decode returned ID %d, want 6", id)
	}
}

func TestShapeIndexEncodeDecodeLarge(t *testing.T) {
	index := NewShapeIndex()
	for i := 0; i < 20; i++ {
		index.Add(RegularLoop(randomPoint(), kmToAngle(500), 100))
	}
	pv := PointVector{}
	for i := 0; i < 500; i++ {
		pv = append(pv, randomPoint())
	}
	index.Add(&pv)
	index.Build()
	got := roundTripShapeIndex(t, index)
	checkShapeIndexEqual(t, index, got)

	// Re-encoding the decoded index produces identical bytes.
	if a, b := encodeShapeIndexOrDie(t, index), encodeShapeIndexOrDie(t, got); !bytes.Equal(a, b) {
		t.Errorf("re-encoding decoded index produced different bytes")
	}
}

func TestShapeIndexDecodeIntoExisting(t *testing.T) {
	src := allShapeTypesIndex()
	data := encodeShapeIndexOrDie(t, src)

	dst := NewShapeIndex()
	dst.Add(makePolyline("50:50, 51:51"))
	dst.Build()
	if err := dst.Decode(bytes.NewReader(data)); err != nil {
		t.Fatalf("Decode() failed: %v", err)
	}
	checkShapeIndexEqual(t, src, dst)

	// A failed decode leaves the destination unchanged.
	before := shapeIndexCellsString(dst)
	if err := dst.Decode(bytes.NewReader(data[:len(data)/2])); err == nil {
		t.Fatalf("Decode() of truncated data succeeded")
	}
	if after := shapeIndexCellsString(dst); after != before || dst.Len() != src.Len() {
		t.Errorf("failed Decode() modified the index")
	}
}

func TestShapeIndexEncodeUnsupportedShape(t *testing.T) {
	index := NewShapeIndex()
	index.Add(&edgeVectorShape{})
	var buf bytes.Buffer
	if err := index.Encode(&buf); err == nil {
		t.Errorf("Encode() of unsupported shape type succeeded")
	}
}

func TestShapeIndexDecodeTruncated(t *testing.T) {
	index := allShapeTypesIndex()
	data := encodeShapeIndexOrDie(t, index)
	for n := 0; n < len(data); n++ {
		var got ShapeIndex
		if err := got.Decode(bytes.NewReader(data[:n])); err == nil {
			t.Fatalf("Decode() of %d/%d bytes succeeded", n, len(data))
		}
	}
}

func TestShapeIndexDecodeCorrupted(t *testing.T) {
	index := allShapeTypesIndex()
	data := encodeShapeIndexOrDie(t, index)
	r := rand.New(rand.NewSource(1))
	for i := 0; i < 3000; i++ {
		corrupt := append([]byte(nil), data...)
		for j := 0; j <= r.Intn(4); j++ {
			corrupt[r.Intn(len(corrupt))] = byte(r.Intn(256))
		}
		var got ShapeIndex
		// Must not panic; an error or a structurally valid index are both acceptable.
		if err := got.Decode(bytes.NewReader(corrupt)); err == nil {
			got.Iterator()
		}
	}
	// Bad version.
	bad := append([]byte(nil), data...)
	bad[0] = 0xFF
	if err := new(ShapeIndex).Decode(bytes.NewReader(bad)); err == nil {
		t.Errorf("Decode() with bad version succeeded")
	}
}

func TestShapeIndexDecodeOversized(t *testing.T) {
	uv := func(xs ...uint64) []byte {
		var out []byte
		for _, x := range xs {
			out = binary.AppendUvarint(out, x)
		}
		return out
	}
	header := func(nextID, numShapes uint64) []byte {
		return append([]byte{shapeIndexEncodingVersion}, uv(10, nextID, numShapes)...)
	}
	tests := []struct {
		name string
		data []byte
	}{
		{"huge next ID", header(1<<40, 0)},
		{"more shapes than IDs", header(2, 3)},
		{"huge shape count", header(1<<31-1, 1<<31-1)},
		{"huge vertex count", append(header(1, 1), append(uv(0), append([]byte{shapeTypePolyline}, uv(1<<40)...)...)...)},
		{"large vertex count, no data", append(header(1, 1), append(uv(0), append([]byte{shapeTypePointVector}, uv(maxEncodedVertices)...)...)...)},
		{"huge loop count", append(header(1, 1), append(uv(0), append([]byte{shapeTypePolygon, 0}, uv(1<<40)...)...)...)},
		{"large loop count, no data", append(header(1, 1), append(uv(0), append([]byte{shapeTypeLaxPolygon}, uv(maxEncodedLoops)...)...)...)},
		{"unknown shape type", append(header(1, 1), append(uv(0), 0x7F)...)},
		{"shape ID out of range", append(header(1, 1), append(uv(5), shapeTypePointVector, 0)...)},
		{"huge cell count", append(header(0, 0), uv(1<<31-1)...)},
		{"invalid cell ID", append(append(header(0, 0), uv(1)...), make([]byte, 8)...)},
		{"overflowing varint", append([]byte{shapeIndexEncodingVersion}, bytes.Repeat([]byte{0xFF}, 11)...)},
	}
	for _, test := range tests {
		var got ShapeIndex
		if err := got.Decode(bytes.NewReader(test.data)); err == nil {
			t.Errorf("%s: Decode() succeeded, want error", test.name)
		}
	}

	// Cells referencing missing shapes or out-of-range edges are rejected.
	index := NewShapeIndex()
	index.Add(makePolyline("0:0, 1:1"))
	data := encodeShapeIndexOrDie(t, index)
	base := append(header(1, 1), uv(0)...)
	shapeData := data[len(base):]
	pl := shapeData[:1+len(uv(2))+2*24]
	cellID := make([]byte, 8)
	binary.LittleEndian.PutUint64(cellID, uint64(CellIDFromFace(0)))
	for name, cell := range map[string][]byte{
		"unknown shape":   uv(1, 7, 0, 0),
		"edge range":      append(uv(1, 0), append([]byte{0}, uv(1, 1)...)...),
		"too many edges":  append(uv(1, 0), append([]byte{0}, uv(5)...)...),
		"too many shapes": uv(2),
		"duplicate shape": append(append(uv(2, 0), append([]byte{0}, uv(0, 0)...)...), 0, 0),
	} {
		buf := append(append(append(append([]byte(nil), base...), pl...), uv(1)...), cellID...)
		buf = append(buf, cell...)
		if err := new(ShapeIndex).Decode(bytes.NewReader(buf)); err == nil {
			t.Errorf("%s: Decode() succeeded, want error", name)
		}
	}
}

